<?php require_once __DIR__.'/../model/doctor_model.php';require_once __DIR__.'/../model/department_model.php';require_once __DIR__.'/../model/appointment_model.php';if($_SESSION['user']['role']!=='admin')exit('Access denied');$dm=new DoctorModel();$dep=new DepartmentModel();$am=new AppointmentModel();$action=$_GET['action']??'admin';$error='';$success='';try{if($action==='save_doctor'){$dm->save(['doctor_id'=>(int)($_POST['doctor_id']??0),'user_id'=>(int)($_POST['user_id']??0),'name'=>trim($_POST['name']),'email'=>trim($_POST['email']),'phone'=>trim($_POST['phone']),'password'=>$_POST['password']??'doctor123','department_id'=>(int)$_POST['department_id'],'specialization'=>trim($_POST['specialization']),'fee'=>(float)$_POST['fee'],'available_days'=>trim($_POST['available_days']),'start_time'=>$_POST['start_time'],'end_time'=>$_POST['end_time'],'room'=>trim($_POST['room'])]);$success='Doctor saved.';}elseif($action==='delete_doctor'){$dm->delete((int)$_GET['id']);$success='Doctor removed.';}elseif($action==='save_department'){$dep->save(trim($_POST['name']));$success='Department added.';}elseif($action==='delete_department'){$dep->delete((int)$_GET['id']);$success='Department removed.';}}catch(Throwable $e){$error='Operation failed: '.$e->getMessage();}$doctors=$dm->all();$departments=$dep->all();$appointments=$am->all($_GET['date']??null,$_GET['doctor_id']??null);require __DIR__.'/../views/admin.php';?>